    // 错误路径：如果后续操作失败，会重复释放
    if (n > 100) {
        // 模拟某些条件
        free(tmp);
        free(buf.data);  // 双重释放
        return -2;
    }

    free(tmp);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file>\n", argv[0]);
