package order

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
)

type OrderInfo struct {
	OrderID string `json:"order_id"`
	Status  string `json:"status"`
	Amount  float64 `json:"amount"`
}

// QueryOrder 根据订单号查询订单详情
func QueryOrder(w http.ResponseWriter, r *http.Request) {
	orderID := r.URL.Query().Get("order_id")
	if orderID == "" {
		http.Error(w, "missing order_id", http.StatusBadRequest)
		return
	}

	// 构造内部订单服务请求
	internalAPI := "http://internal-order-svc:8080/orders/"
	reqURL := internalAPI + orderID

	// 发起HTTP请求获取订单数据
	resp, err := http.Get(reqURL)
	if err != nil {
		http.Error(w, "failed to fetch order", http.StatusInternalServerError)
		return
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		http.Error(w, "failed to read response", http.StatusInternalServerError)
		return
	}

	// 解析并返回订单信息
	var order OrderInfo
	if err := json.Unmarshal(body, &order); err != nil {
		http.Error(w, "invalid order data", http.StatusInternalServerError)
		return
	}

	// 检查响应状态
	if resp.StatusCode != http.StatusOK {
		http.Error(w, "order service error", http.StatusBadGateway)
		return
	}

	// 返回订单信息
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(order)
}


