package main

import (
	"fmt"
	"os/exec"
	"strings"
	"time"
)

// allowedCommands 定义定时任务允许执行的命令白名单
var allowedCommands = map[string]bool{
	"backup":   true,
	"cleanup":  true,
	"report":   true,
	"health":   true,
}

// runScheduledTask 执行定时任务，仅允许白名单内的命令
func runScheduledTask(taskName string) error {
	// 第1行：白名单校验，拒绝非白名单命令
	if !allowedCommands[taskName] {
		return fmt.Errorf("task %q is not allowed", taskName)
	}

	// 第2行：构造命令参数列表，不使用 shell
	// 第3行：参数固定，不包含任何用户可控数据
	args := []string{taskName, "--env=production", "--timeout=30"}

	// 第4行：使用 exec.Command 直接执行，shell=false（默认）
	cmd := exec.Command("/usr/local/bin/task-runner", args...)

	// 第5行：执行命令并捕获输出
	output, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("task %q failed: %v, output: %s", taskName, err, string(output))
	}

	// 第6行：记录执行结果
	fmt.Printf("task %q completed: %s\n", taskName, strings.TrimSpace(string(output)))
	return nil
}

// scheduleLoop 定时任务调度循环
func scheduleLoop() {
	ticker := time.NewTicker(5 * time.Minute)
	defer ticker.Stop()

	for range ticker.C {
		// 第7行：任务名称来自固定配置，非用户输入
		tasks := []string{"backup", "cleanup", "health"}
		for _, task := range tasks {
			if err := runScheduledTask(task); err != nil {
				fmt.Printf("scheduled task error: %v\n", err)
			}
		}
	}
}

func main() {
	// 第8行：启动调度循环
	scheduleLoop()
}


