package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"os/exec"
	"strings"
)

type BuildRequest struct {
	Image string `json:"image"`
	Tag   string `json:"tag"`
}

var allowedImages = map[string]bool{
	"nginx":     true,
	"redis":     true,
	"postgres":  true,
	"golang":    true,
	"node":      true,
}

func buildHandler(w http.ResponseWriter, r *http.Request) {
	var req BuildRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid JSON", http.StatusBadRequest)
		return
	}

	// 第20行：白名单校验镜像名
	if !allowedImages[req.Image] {
		http.Error(w, "image not allowed", http.StatusForbidden)
		return
	}

	// 第24行：Tag 格式校验（仅允许字母数字和 . - _）
	for _, ch := range req.Tag {
		if !(ch >= 'a' && ch <= 'z') && !(ch >= 'A' && ch <= 'Z') &&
			!(ch >= '0' && ch <= '9') && ch != '.' && ch != '-' && ch != '_' {
			http.Error(w, "invalid tag format", http.StatusBadRequest)
			return
		}
	}

	// 第32行：使用列表参数 + shell=False，避免 shell 解释
	cmd := exec.Command("docker", "build", "-t", req.Image+":"+req.Tag, ".")
	output, err := cmd.CombinedOutput()
	if err != nil {
		fmt.Printf("build failed: %v\n", err)
		http.Error(w, "build failed", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
	w.Write(output)
}

func main() {
	http.HandleFunc("/build", buildHandler)
	http.ListenAndServe(":8080", nil)
}


