class FileHandle {
public:
    explicit FileHandle(const char* path) : data(nullptr) {
        FILE* fp = fopen(path, "rb");
        if (fp) {
            fseek(fp, 0, SEEK_END);
            long size = ftell(fp);
            fseek(fp, 0, SEEK_SET);
            data = (char*)malloc(size + 1);
            if (data) {
                fread(data, 1, size, fp);
                data[size] = '\0';
            }
            fclose(fp);
        }
    }
    ~FileHandle() {
        if (data) {
            free(data);
            data = nullptr;  // line 21: 置空防止 double free
        }
    }
    char* get() { return data; }
private:
    char* data;
};

int processFile(const char* path) {
    FileHandle fh(path);  // line 27: RAII 管理，析构自动释放
    char* content = fh.get();
