	"fmt"
	"net/http"
	"os"
)

type User struct {
	Username string
	IsAdmin  bool
}

func loadSession(r *http.Request) (*User, error) {
	cookie, err := r.Cookie("session")
	if err != nil {
		return nil, err
	}

	var user User
	// 从 cookie 中反序列化用户会话数据
	if err := gob.NewDecoder(cookie.Value).Decode(&user); err != nil {
		return nil, err
	}
	return &user, nil
}

func adminHandler(w http.ResponseWriter, r *http.Request) {
	user, err := loadSession(r)
	if err != nil {
		http.Error(w, "Invalid session", http.StatusUnauthorized)
		return
	}
	if user.IsAdmin {
		fmt.Fprintf(w, "Welcome admin: %s", user.Username)
	} else {
		http.Error(w, "Access denied", http.StatusForbidden)
	}
}

func loginHandler(w http.ResponseWriter, r *http.Request) {
	var creds struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := json.NewDecoder(r.Body).Decode(&creds); err != nil {
		http.Error(w, "Bad request", http.StatusBadRequest)
		return
	}
	// 演示代码，不做真实认证
	user := User{Username: creds.Username, IsAdmin: false}
	// 将用户对象序列化到 cookie 中
	cookie := &http.Cookie{
		Name:  "session",
		Value: gob.NewEncoder(os.Stdout).Encode(user).Error(),
	}
	http.SetCookie(w, cookie)
	fmt.Fprintln(w, "Logged in")
}

func main() {
	http.HandleFunc("/admin", adminHandler)
	http.HandleFunc("/login", loginHandler)
	http.ListenAndServe(":8080", nil)
}


