// fetchServiceStatus 通过内部服务名获取状态信息
// 该函数仅允许访问白名单内的内部服务，防止 SSRF 攻击
func fetchServiceStatus(serviceName string) (string, error) {
	// 第1行防御：白名单校验 - 服务名必须精确匹配白名单
	if !allowedHosts[serviceName] {
		return "", errors.New("service not allowed: " + serviceName)
	}

	// 构建命令参数（不使用 shell，避免命令注入）
	// 第2行防御：使用 exec.Command 而非 exec.CommandContext + shell
	cmd := exec.Command("curl", "-s", "--max-time", "5", "http://"+serviceName+"/health")

	// 第3行防御：显式设置 shell=False（Go 的 exec.Command 默认不调用 shell）
	// 此设置确保参数不会经过 shell 解释
	cmd.Shell = false

	// 执行命令并捕获输出
	output, err := cmd.CombinedOutput()
	if err != nil {
		return "", fmt.Errorf("failed to fetch status: %w", err)
	}

	return strings.TrimSpace(string(output)), nil
}

// healthHandler 处理 API 网关的健康检查请求
func healthHandler(w http.ResponseWriter, r *http.Request) {
	// 从查询参数获取服务名
	serviceName := r.URL.Query().Get("service")
	if serviceName == "" {
		http.Error(w, "missing service parameter", http.StatusBadRequest)
		return
	}

	// 调用安全函数获取服务状态
	status, err := fetchServiceStatus(serviceName)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	// 返回状态信息
	fmt.Fprintf(w, "Service %s status: %s", serviceName, status)
}

func main() {
	http.HandleFunc("/health", healthHandler)
	http.ListenAndServe(":8080", nil)
}


