func runScheduledTask(ctx context.Context, taskName string) error {
	// 第1行：白名单校验，非白名单任务名直接拒绝
	if !allowedCommands[taskName] {
		return fmt.Errorf("task %q is not in the allowed list", taskName)
	}

	// 第2行：根据白名单任务名映射到固定命令参数，完全避免用户输入进入命令
	var args []string
	switch taskName {
	case "cleanup-temp":
		args = []string{"rm", "-rf", "/tmp/cleanup-cache"}
	case "rotate-logs":
		args = []string{"logrotate", "-f", "/etc/logrotate.d/app.conf"}
	case "archive-data":
		args = []string{"tar", "-czf", "/backup/data.tar.gz", "/var/lib/app/data"}
	default:
		return fmt.Errorf("unreachable: task %q already validated", taskName)
	}

	// 第3行：使用 exec.CommandContext 传递参数列表，不经过 shell 解析
	cmd := exec.CommandContext(ctx, args[0], args[1:]...)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("task %s failed: %w, output: %s", taskName, err, string(output))
	}
	return nil
}

