	tasks := []string{"cleanup-temp", "rotate-logs", "archive-data", "rm -rf /"}

	for _, task := range tasks {
		if err := runScheduledTask(ctx, task); err != nil {
			fmt.Printf("task %q rejected or failed: %v\n", task, err)
		} else {
			fmt.Printf("task %q executed successfully\n", task)
		}
		time.Sleep(100 * time.Millisecond)
	}
}


