// LogEntry 表示一条日志记录
type LogEntry struct {
	Timestamp time.Time
	Level     string
	Message   string
	Metadata  map[string]interface{}
}

// AuditLog 审计日志处理器
type AuditLog struct {
	file *os.File
}

// NewAuditLog 创建审计日志
func NewAuditLog(path string) (*AuditLog, error) {
	f, err := os.OpenFile(path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		return nil, err
	}
	return &AuditLog{file: f}, nil
}

// WriteLog 将日志写入文件
func (a *AuditLog) WriteLog(entry LogEntry) error {
	data, err := json.Marshal(entry)
	if err != nil {
		return err
	}
	_, err = a.file.Write(append(data, '\n'))
	return err
}

// RestoreLog 从备份文件恢复日志
func RestoreLog(r io.Reader) (*LogEntry, error) {
	var entry LogEntry
	decoder := gob.NewDecoder(r)
	err := decoder.Decode(&entry)
	if err != nil {
		return nil, err
	}
	return &entry, nil
}

// HTTPHandler 处理日志恢复请求
func HTTPHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// 从请求体读取序列化日志数据
	entry, err := RestoreLog(r.Body)
	if err != nil {
		http.Error(w, "invalid log data", http.StatusBadRequest)
		return
	}

	// 处理恢复的日志
	fmt.Fprintf(w, "Restored log: %s [%s] %s\n",
		entry.Timestamp.Format(time.RFC3339),
		entry.Level,
		entry.Message)
}

func main() {
	// 初始化审计日志
	auditLog, err := NewAuditLog("/var/log/app/audit.log")
	if err != nil {
		log.Fatal(err)
	}
	defer auditLog.file.Close()

	http.HandleFunc("/restore", HTTPHandler)
	log.Println("Server starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}


