class SharedBuffer {
public:
    SharedBuffer() : data_(nullptr), ready_(false) {}

    void produce() {
        std::unique_lock<std::mutex> lock(mtx_);
        data_ = new int(42);  // line 11: 分配资源
        ready_ = true;
        cv_.notify_one();
        // 模拟一些额外工作
