        // 故意不释放 data_，等待消费者处理
    }

    void consume() {
        std::unique_lock<std::mutex> lock(mtx_);
        cv_.wait(lock, [this] { return ready_; });

        // 消费者使用 data_ 后释放
        if (data_) {
            std::cout << "Consumed: " << *data_ << std::endl;
            delete data_;      // line 23: 消费者释放
            data_ = nullptr;   // line 24: 置空防御
        }
    }

    void reset() {
        std::unique_lock<std::mutex> lock(mtx_);
        // 重置状态，但未检查 data_ 是否已被释放
        ready_ = false;
        // 这里存在潜在问题：如果 consume 还没执行，data_ 仍指向有效内存
        // 但 produce 再次调用时会直接覆盖指针
    }

private:
    std::mutex mtx_;
    std::condition_variable cv_;
    int* data_;
    bool ready_;
};

void worker_producer(SharedBuffer& buf) {
    buf.produce();
}

void worker_consumer(SharedBuffer& buf) {
    buf.consume();
}

int main() {
    SharedBuffer buf;

    // 场景1: 正常生产-消费
    std::thread t1(worker_producer, std::ref(buf));
    std::thread t2(worker_consumer, std::ref(buf));
    t1.join();
    t2.join();

    // 场景2: 第二次生产，但消费者可能未及时运行
    std::thread t3(worker_producer, std::ref(buf));
