struct BitmapHeader {
    uint32_t dataOffset;
    uint32_t width;
    uint32_t height;
    uint16_t bitsPerPixel;
};

bool loadBitmap(const char* filePath, std::vector<uint8_t>& pixelData, BitmapHeader& header) {
    std::ifstream file(filePath, std::ios::binary);
    if (!file.is_open()) return false;

    file.read(reinterpret_cast<char*>(&header.dataOffset), 4);
    file.read(reinterpret_cast<char*>(&header.width), 4);
    file.read(reinterpret_cast<char*>(&header.height), 4);
    file.read(reinterpret_cast<char*>(&header.bitsPerPixel), 2);

    if (header.bitsPerPixel != 24 && header.bitsPerPixel != 32) return false;

    // 行大小按4字节对齐（BMP格式要求）
    uint32_t rowSize = ((header.width * header.bitsPerPixel + 31) / 32) * 4;
    uint32_t imageSize = rowSize * header.height;

    // 缺少对 imageSize 与文件实际大小的校验
    pixelData.resize(imageSize);

    file.seekg(header.dataOffset, std::ios::beg);
    file.read(reinterpret_cast<char*>(pixelData.data()), imageSize);

    return file.good();
}

// 调用示例：解码后的像素用于后续处理
void decodePixels(const std::vector<uint8_t>& raw, int width, int height) {
    // 假设每个像素3字节（RGB），此处处理逻辑省略
    uint8_t* frame = new uint8_t[width * height * 3];
    for (int i = 0; i < height; ++i) {
        for (int j = 0; j < width; ++j) {
            int idx = (i * width + j) * 3;
            frame[idx] = raw[idx];     // 越界读取点
            frame[idx + 1] = raw[idx + 1];
            frame[idx + 2] = raw[idx + 2];
        }
    }
    delete[] frame;
}

int main(int argc, char* argv[]) {
    if (argc < 2) return 1;
    BitmapHeader header;
    std::vector<uint8_t> pixels;
    if (!loadBitmap(argv[1], pixels, header)) return 1;
    decodePixels(pixels, header.width, header.height);
    return 0;
}


