#define MAX_CMD_LEN 64
#define CMD_QUEUE_SIZE 8

typedef struct {
    char cmd[MAX_CMD_LEN];
    uint8_t len;
    uint8_t valid;
} CommandEntry;

typedef struct {
    CommandEntry entries[CMD_QUEUE_SIZE];
    uint8_t head;
    uint8_t tail;
    uint8_t count;
} CommandQueue;

static void queue_init(CommandQueue *q) {
    memset(q, 0, sizeof(CommandQueue));
}

static uint8_t queue_push(CommandQueue *q, const char *cmd, uint8_t len) {
    if (q->count >= CMD_QUEUE_SIZE) {
        return 0;  // Queue full
    }
    if (len >= MAX_CMD_LEN) {
        return 0;  // Command too long
    }
    CommandEntry *e = &q->entries[q->tail];
    memcpy(e->cmd, cmd, len);  // line 12: bounded copy
    e->cmd[len] = '\0';        // line 13: explicit terminator
    e->len = len;
    e->valid = 1;
    q->tail = (q->tail + 1) % CMD_QUEUE_SIZE;
    q->count++;
    return 1;
}

static uint8_t queue_pop(CommandQueue *q, char *out, uint8_t max_out) {
    if (q->count == 0) {
        return 0;
    }
    CommandEntry *e = &q->entries[q->head];
    uint8_t copy_len = e->len;
    if (copy_len > max_out) {
        copy_len = max_out;  // line 24: clamp to output buffer
    }
    memcpy(out, e->cmd, copy_len);
    out[copy_len] = '\0';
    e->valid = 0;
    q->head = (q->head + 1) % CMD_QUEUE_SIZE;
    q->count--;
    return copy_len;
}

// Firmware command processor (called from UART interrupt handler)
void process_uart_command(const char *rx_buffer, uint8_t rx_len) {
    CommandQueue queue;
    queue_init(&queue);

    if (!queue_push(&queue, rx_buffer, rx_len)) {
        // Reject invalid command
        return;
    }

    char output[32];
    uint8_t out_len = queue_pop(&queue, output, sizeof(output) - 1);
    if (out_len > 0) {
        // Execute command (simulated)
        output[out_len] = '\0';
        (void)output;
    }
}


