struct Resource {
    int* data;
    int size;
};

Resource* create_resource(int size) {
    Resource* res = new Resource;
    res->size = size;
    res->data = (int*)malloc(size * sizeof(int));
    if (!res->data) {
        delete res;
        return nullptr;
    }
    return res;
}

void release_resource(Resource* res) {
    if (!res) return;
    free(res->data);
    delete res;
}

pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;
Resource* g_shared = nullptr;

void* consumer_thread(void* arg) {
    (void)arg;
    for (int i = 0; i < 3; ++i) {
        pthread_mutex_lock(&g_mutex);
        Resource* local = g_shared;
        if (local) {
            printf("Consumer: %d\n", local->data[0]);
        }
        pthread_mutex_unlock(&g_mutex);
        usleep(10000);
    }
    return nullptr;
}

void* cleanup_thread(void* arg) {
    (void)arg;
    usleep(5000);
    pthread_mutex_lock(&g_mutex);
    if (g_shared) {
        release_resource(g_shared);  // line 43: first free
        g_shared = nullptr;          // line 44: set NULL (safe)
    }
    pthread_mutex_unlock(&g_mutex);
    return nullptr;
}

void* race_thread(void* arg) {
    (void)arg;
    usleep(2000);
    pthread_mutex_lock(&g_mutex);
    if (g_shared) {
        release_resource(g_shared);  // line 53: second free (double free)
        // missing: g_shared = nullptr;
    }
    pthread_mutex_unlock(&g_mutex);
    return nullptr;
}

int main() {
