    if (!g_shared) return 1;

    pthread_t t1, t2, t3;
    pthread_create(&t1, nullptr, consumer_thread, nullptr);
    pthread_create(&t2, nullptr, cleanup_thread, nullptr);
    pthread_create(&t3, nullptr, race_thread, nullptr);

    pthread_join(t1, nullptr);
    pthread_join(t2, nullptr);
    pthread_join(t3, nullptr);

    pthread_mutex_destroy(&g_mutex);
    return 0;
