size_t read_file(const char* path, char*& out_buf) {
    std::ifstream file(path, std::ios::binary | std::ios::ate);
    if (!file.is_open()) {
        out_buf = nullptr;
        return 0;
    }
    std::streamsize fsize = file.tellg();
    file.seekg(0, std::ios::beg);
    out_buf = new char[static_cast<size_t>(fsize) + 1];
    file.read(out_buf, fsize);
    out_buf[fsize] = '\0';
    return static_cast<size_t>(fsize);
}

// Process a configuration file: copy its contents into a fixed-size struct
struct Config {
    char name[16];
    char path[32];
    uint32_t flags;
};

bool load_config(const char* filename, Config& cfg) {
    char* raw = nullptr;
    size_t len = read_file(filename, raw);
    if (!raw || len == 0) {
        delete[] raw;
        return false;
    }

    // Simulate parsing: copy the first 16 bytes as name, next 32 as path
    // Vulnerability: no bounds check against raw buffer length before memcpy
    memcpy(cfg.name, raw, 16);          // line 30: potential overflow if len < 16
    memcpy(cfg.path, raw + 16, 32);     // line 31: potential overflow if len < 48
