    return true;
}

int parseHeader(const std::vector<uint8_t>& data) {
    // Header layout: [2-byte magic][2-byte version][4-byte entry_count]
    if (data.size() < 8) {
        std::cerr << "Too small." << std::endl;
        return -1;
    }

    uint16_t magic;
    std::memcpy(&magic, data.data(), 2);
    if (magic != 0x5A5A) {
        std::cerr << "Bad magic." << std::endl;
        return -1;
    }

    uint32_t entry_count;
    std::memcpy(&entry_count, data.data() + 4, 4);

    // Assume each entry is 4 bytes: [2-byte offset][2-byte len]
    // entry_count is controlled by file content
    uint16_t first_offset;
    std::memcpy(&first_offset, data.data() + 8, 2);  // line 36: potential OOB read if entry_count > 0 but data.size() < 10

    std::cout << "First entry offset: " << first_offset << std::endl;
    return static_cast<int>(entry_count);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <config.bin>" << std::endl;
        return 1;
    }

    std::vector<uint8_t> fileData;
    if (!readConfig(argv[1], fileData)) {
        return 1;
    }

    int count = parseHeader(fileData);
    if (count < 0) return 1;

    std::cout << "Parsed " << count << " entries." << std::endl;
    return 0;
}


