package main

import (
	"encoding/gob"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
)

type UploadHandler struct {
	UploadDir string
}

// handleUpload processes file upload and deserializes metadata
func (h *UploadHandler) handleUpload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Limit upload size to 10MB
	r.Body = http.MaxBytesReader(w, r.Body, 10<<20)

	file, header, err := r.FormFile("file")
	if err != nil {
		http.Error(w, "invalid file", http.StatusBadRequest)
		return
	}
	defer file.Close()

	// Sanitize filename to prevent path traversal
	filename := filepath.Base(header.Filename)
	dstPath := filepath.Join(h.UploadDir, filename)

	dst, err := os.Create(dstPath)
	if err != nil {
		http.Error(w, "failed to create file", http.StatusInternalServerError)
		return
	}
	defer dst.Close()

	// Copy file content
	if _, err := io.Copy(dst, file); err != nil {
		http.Error(w, "failed to save file", http.StatusInternalServerError)
		return
	}

	// Deserialize metadata from the uploaded file header
	// The file format includes a gob-encoded metadata struct
	metaFile, err := header.Open()
	if err != nil {
		http.Error(w, "failed to open metadata", http.StatusInternalServerError)
		return
	}
	defer metaFile.Close()

	var metadata map[string]interface{}
	decoder := gob.NewDecoder(metaFile)
	if err := decoder.Decode(&metadata); err != nil {
		http.Error(w, "invalid metadata", http.StatusBadRequest)
		return
	}

	// Process metadata - could trigger arbitrary code execution
	processMetadata(metadata)
	fmt.Fprintf(w, "upload success: %s", filename)
}

func processMetadata(meta map[string]interface{}) {
	// Simulate processing that uses metadata fields
	if val, ok := meta["action"].(string); ok {
		fmt.Println("Action:", val)
	}
}

func main() {
	handler := &UploadHandler{UploadDir: "/tmp/uploads"}
	http.HandleFunc("/upload", handler.handleUpload)
	http.ListenAndServe(":8080", nil)
}


