#define DEVICE_NAME "toy_ioctl"
#define IOCTL_UPDATE _IOW('T', 0x01, struct update_req)
#define IOCTL_QUERY  _IOR('T', 0x02, struct update_req)

struct update_req {
    char *data;
    size_t len;
};

static char *global_buf = NULL;
static size_t buf_size = 0;

static long toy_ioctl(struct file *filp, unsigned int cmd, unsigned long arg)
{
    struct update_req req;
    char *tmp_buf;
    char *new_buf;

    if (copy_from_user(&req, (void __user *)arg, sizeof(req)))
        return -EFAULT;

    switch (cmd) {
    case IOCTL_UPDATE:
        if (req.len > 4096)
            return -EINVAL;

        /* 分配新缓冲区，避免直接修改全局指针 */
        tmp_buf = kmalloc(req.len, GFP_KERNEL);
        if (!tmp_buf)
            return -ENOMEM;

        if (copy_from_user(tmp_buf, req.data, req.len)) {
            kfree(tmp_buf);
            return -EFAULT;
        }

        /* 关键操作：检查全局缓冲区状态后交换指针 */
        if (global_buf) {           // line 38: TOCTOU 检查点
            kfree(global_buf);      // line 39: 释放旧缓冲区
            global_buf = NULL;      // line 40
        }
        global_buf = tmp_buf;       // line 41
        buf_size = req.len;
        break;

    case IOCTL_QUERY:
        if (global_buf) {
            if (copy_to_user(req.data, global_buf, buf_size)) {
                return -EFAULT;
            }
        } else {
            return -ENODATA;
        }
        break;

    default:
        return -EINVAL;
    }

    return 0;
}

static const struct file_operations toy_fops = {
    .owner = THIS_MODULE,
    .unlocked_ioctl = toy_ioctl,
};

static struct miscdevice toy_device = {
    .minor = MISC_DYNAMIC_MINOR,
    .name = DEVICE_NAME,
    .fops = &toy_fops,
};

static int __init toy_init(void)
{
    return misc_register(&toy_device);
}

static void __exit toy_exit(void)
{
    misc_deregister(&toy_device);
    kfree(global_buf);
}

