#include <linux/kernel.h>
#include <linux/module.h>
#include <linux/device.h>
#include <linux/slab.h>
#include <linux/uaccess.h>
#include <linux/ioctl.h>
#include <linux/mutex.h>

#define DEV_NAME "vuln_dev"
#define BUF_SIZE 128
#define CMD_WRITE 0x1001
#define CMD_READ  0x1002

static struct mutex lock;
static char *dev_buffer;
static int dev_open_count = 0;

static long dev_ioctl(struct file *filp, unsigned int cmd, unsigned long arg)
{
    int ret = 0;
    unsigned long copy_len;

    mutex_lock(&lock);

    switch (cmd) {
    case CMD_WRITE:
        if (copy_from_user(&copy_len, (void __user *)arg, sizeof(copy_len))) {
            ret = -EFAULT;
            break;
        }
        if (copy_len > BUF_SIZE) {
            ret = -EINVAL;
            break;
        }
        if (copy_from_user(dev_buffer, (void __user *)(arg + sizeof(copy_len)), copy_len)) {
            ret = -EFAULT;
            break;
        }
        break;

    case CMD_READ:
        if (copy_to_user((void __user *)arg, dev_buffer, BUF_SIZE)) {
            ret = -EFAULT;
        }
        break;

    default:
        ret = -ENOTTY;
        break;
    }

    mutex_unlock(&lock);
    return ret;
}

static int dev_open(struct inode *inode, struct file *filp)
{
    mutex_lock(&lock);
    if (dev_open_count > 0) {
        mutex_unlock(&lock);
        return -EBUSY;
    }
    dev_open_count++;
    mutex_unlock(&lock);
    return 0;
}

static int dev_release(struct inode *inode, struct file *filp)
{
    mutex_lock(&lock);
    dev_open_count--;
    mutex_unlock(&lock);
    return 0;
}

static const struct file_operations fops = {
    .owner = THIS_MODULE,
    .open = dev_open,
    .release = dev_release,
    .unlocked_ioctl = dev_ioctl,
};

static int __init dev_init(void)
{
    mutex_init(&lock);
    dev_buffer = kmalloc(BUF_SIZE, GFP_KERNEL);
    if (!dev_buffer)
        return -ENOMEM;
    if (register_chrdev(0, DEV_NAME, &fops) < 0) {
        kfree(dev_buffer);
        return -ENODEV;
    }
    return 0;
}

static void __exit dev_exit(void)
{
    unregister_chrdev(0, DEV_NAME);
    kfree(dev_buffer);
}

module_init(dev_init);
module_exit(dev_exit);
MODULE_LICENSE("GPL");


