#include <linux/slab.h>
#include <linux/uaccess.h>
#include <linux/device.h>
#include <linux/fs.h>
#include <linux/module.h>
#include <linux/ioctl.h>

#define DRIVER_NAME "vuln_dev"
#define IOCTL_SET_BUF_SIZE _IOW('V', 0x01, int)
#define IOCTL_WRITE_DATA  _IOW('V', 0x02, struct write_arg)

struct write_arg {
    int index;
    char data[128];
};

struct device_ctx {
    int buf_size;
    char *buf;
    struct mutex lock;
};

static struct device_ctx *ctx;

static int dev_open(struct inode *inode, struct file *filp)
{
    ctx = kzalloc(sizeof(struct device_ctx), GFP_KERNEL);
    if (!ctx)
        return -ENOMEM;
    mutex_init(&ctx->lock);
    ctx->buf_size = 256;
    ctx->buf = kmalloc(ctx->buf_size, GFP_KERNEL);
    if (!ctx->buf) {
        kfree(ctx);
        return -ENOMEM;
    }
    filp->private_data = ctx;
    return 0;
}

static long dev_ioctl(struct file *filp, unsigned int cmd, unsigned long arg)
{
    struct device_ctx *dctx = filp->private_data;
    struct write_arg wa;
    int new_size;

    mutex_lock(&dctx->lock);

    switch (cmd) {
    case IOCTL_SET_BUF_SIZE:
        if (copy_from_user(&new_size, (void __user *)arg, sizeof(int))) {
            mutex_unlock(&dctx->lock);
            return -EFAULT;
        }
        if (new_size < 0 || new_size > 4096) {
            mutex_unlock(&dctx->lock);
            return -EINVAL;
        }
        dctx->buf_size = new_size;
        break;

    case IOCTL_WRITE_DATA:
        if (copy_from_user(&wa, (void __user *)arg, sizeof(wa))) {
            mutex_unlock(&dctx->lock);
            return -EFAULT;
        }
        if (wa.index < 0 || wa.index >= dctx->buf_size) {
            mutex_unlock(&dctx->lock);
            return -EINVAL;
        }
        memcpy(dctx->buf + wa.index, wa.data, sizeof(wa.data));
        break;

    default:
        mutex_unlock(&dctx->lock);
        return -EINVAL;
    }

    mutex_unlock(&dctx->lock);
    return 0;
}

static int dev_release(struct inode *inode, struct file *filp)
{
    struct device_ctx *dctx = filp->private_data;
    mutex_destroy(&dctx->lock);
    kfree(dctx->buf);
    kfree(dctx);
    return 0;
}

static const struct file_operations fops = {
    .open = dev_open,
    .unlocked_ioctl = dev_ioctl,
    .release = dev_release,
};

static int __init vuln_init(void)
{
    register_chrdev(0, DRIVER_NAME, &fops);
    return 0;
}
module_init(vuln_init);
module_exit(cleanup_module);
MODULE_LICENSE("GPL");


