class BlockAllocator {
public:
    // 安全：使用RAII管理文件句柄，避免资源泄漏
    BlockAllocator(const std::string& path) : file_(path, std::ios::binary | std::ios::out) {
        if (!file_.is_open()) {
            throw std::runtime_error("无法打开文件");
        }
    }

    // 跨函数调用场景：分配多个块
    bool allocate_blocks(uint32_t start_block, uint32_t num_blocks, std::vector<uint32_t>& out_blocks) {
        // line 25: 关键防御点 - 使用安全宏进行加法运算，防止整数溢出
        uint32_t end_block;
        if (!SAFE_ADD(start_block, num_blocks, end_block)) {
            std::cerr << "块范围溢出" << std::endl;
            return false;
        }

        // line 30: 二次防御 - 验证逻辑边界（文件系统最大块数）
        const uint32_t MAX_BLOCKS = 1024 * 1024;  // 1M块上限
        if (end_block > MAX_BLOCKS || start_block > MAX_BLOCKS) {
            std::cerr << "超出文件系统限制" << std::endl;
            return false;
        }

        // 分配并写入块记录
        for (uint32_t i = start_block; i < end_block; ++i) {
            out_blocks.push_back(i);
            // 模拟写入磁盘
            file_.write(reinterpret_cast<const char*>(&i), sizeof(i));
            if (!file_.good()) {
                std::cerr << "写入失败" << std::endl;
                return false;
            }
        }
        return true;
    }

