            model.addAttribute("error", "认证失败");
            return "login";
        }
    }

    private boolean authenticateWithLdap(String username, String password) {
        Hashtable<String, String> env = new Hashtable<>();
        env.put(Context.INITIAL_CONTEXT_FACTORY, "com.sun.jndi.ldap.LdapCtxFactory");
        env.put(Context.PROVIDER_URL, LDAP_URL);
        env.put(Context.SECURITY_AUTHENTICATION, "simple");
        env.put(Context.SECURITY_PRINCIPAL, "cn=admin,dc=company,dc=com");
        env.put(Context.SECURITY_CREDENTIALS, "adminSecret");

        try {
            DirContext ctx = new InitialDirContext(env);

            // 4. 关键：直接拼接用户输入到 LDAP 过滤器（CWE-90）
            String filter = "(&(uid=" + username + ")(userPassword=" + password + "))";

            SearchControls controls = new SearchControls();
            controls.setSearchScope(SearchControls.SUBTREE_SCOPE);

            NamingEnumeration<SearchResult> results = ctx.search(BASE_DN, filter, controls);

            boolean found = results.hasMore();
            ctx.close();
            return found;
        } catch (NamingException e) {
            return false;
        }
    }
}


