// 基于 Flask 风格的 Java API 框架（模拟 Javalin/SparkJava）
import io.javalin.Javalin;
import io.javalin.http.Context;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;

public class UserSearchApi {

    public static void main(String[] args) {
        Javalin app = Javalin.create().start(7000);

        app.get("/api/search", ctx -> {
            String keyword = ctx.queryParam("q");           // line 1: 从请求获取搜索关键词
            String category = ctx.queryParam("cat");        // line 2: 获取分类参数

            // 防御层1: 基础输入校验 - 关键词非空且长度限制
            if (keyword == null || keyword.trim().isEmpty() 
                || keyword.length() > 50) {                  // line 3-4
                ctx.status(400).result("{\"error\":\"invalid keyword\"}");
                return;
            }

            // 防御层2: 分类参数白名单校验
            String safeCategory = whitelistCategory(category);  // line 5
            if (safeCategory == null) {
                ctx.status(400).result("{\"error\":\"invalid category\"}");
                return;
            }

            // 防御层3: 使用参数化查询防止SQL注入
            String sql = "SELECT username, bio FROM users "
                       + "WHERE username LIKE ? AND category = ?";
            try (Connection conn = getConnection();
                 PreparedStatement ps = conn.prepareStatement(sql)) {
                ps.setString(1, "%" + keyword + "%");
                ps.setString(2, safeCategory);

                try (ResultSet rs = ps.executeQuery()) {
                    StringBuilder json = new StringBuilder("[");
                    while (rs.next()) {
                        String username = rs.getString("username");
                        String bio = rs.getString("bio");

                        // 防御层4: 对输出数据进行HTML转义（防止XSS）
                        String safeUsername = escapeHtml(username);
                        String safeBio = escapeHtml(bio);

                        json.append("{\"username\":\"")
                            .append(safeUsername)
                            .append("\",\"bio\":\"")
                            .append(safeBio)
                            .append("\"},");
                    }
                    if (json.length() > 1) {
                        json.setLength(json.length() - 1);
                    }
                    json.append("]");
                    ctx.contentType("application/json").result(json.toString());
                }
            } catch (Exception e) {
                ctx.status(500).result("{\"error\":\"internal error\"}");
            }
        });
    }

    // 白名单校验分类参数
    private static String whitelistCategory(String category) {
        if (category == null) return null;
        // 仅允许预定义的三个分类值
        if (category.equals("developer") || 
            category.equals("designer") || 
            category.equals("manager")) {
            return category;
        }
        return null;
    }

    // HTML实体转义防御XSS
    private static String escapeHtml(String input) {
        if (input == null) return "";
        return input.replace("&", "&amp;")
                   .replace("<", "&lt;")
                   .replace(">", "&gt;")
                   .replace("\"", "&quot;")
                   .replace("'", "&#x27;");
    }

    // 模拟数据库连接
    private static Connection getConnection() {
        // 实际项目中这里是真实连接
        return null;
    }
}


