#include <cstdint>
#include <vector>
#include <cstring>
#include <fstream>
#include <iostream>

struct ImageHeader {
    uint16_t width;
    uint16_t height;
    uint8_t bpp;  // bytes per pixel
} __attribute__((packed));

bool loadImage(const char* path, std::vector<uint8_t>& pixels,
               uint32_t& width, uint32_t& height) {
    std::ifstream file(path, std::ios::binary);
    if (!file.is_open()) return false;

    ImageHeader hdr;
    file.read(reinterpret_cast<char*>(&hdr), sizeof(hdr));
    if (file.gcount() != sizeof(hdr)) return false;

    // Sanity check on dimensions (defense: reject absurd sizes)
    if (hdr.width == 0 || hdr.height == 0 || hdr.bpp != 3) return false;

    width = hdr.width;
    height = hdr.height;

    uint32_t rowSize = width * hdr.bpp;          // bytes per row
    uint32_t pixelDataSize = rowSize * height;   // total bytes

    // Defense: cap allocation to avoid overflow, but allow large images
    if (pixelDataSize > (1 << 20)) return false;  // max 1MB

    pixels.resize(pixelDataSize);

