    for (uint16_t y = 0; y < height; ++y) {
        file.read(reinterpret_cast<char*>(&pixels[y * rowSize]), rowSize);  // line 42
        if (file.gcount() != static_cast<std::streamsize>(rowSize)) {
            pixels.clear();
            return false;
        }
    }

    return true;
}

