package api

import (
	"encoding/json"
	"io"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strings"
)

type ExportRequest struct {
	ReportURL string `json:"report_url"`
	Format    string `json:"format"`
}

// ExportReport fetches a remote report and saves it locally
func ExportReport(w http.ResponseWriter, r *http.Request) {
	var req ExportRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid request", http.StatusBadRequest)
		return
	}

	// Validate format
	if req.Format != "pdf" && req.Format != "csv" {
		http.Error(w, "unsupported format", http.StatusBadRequest)
		return
	}

	// Fetch the remote report
	resp, err := http.Get(req.ReportURL)
	if err != nil {
		http.Error(w, "failed to fetch report", http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()

	// Sanitize filename from URL
	parsed, _ := url.Parse(req.ReportURL)
	filename := filepath.Base(parsed.Path)
	if filename == "." || filename == "/" || filename == "" {
		filename = "report_" + req.Format
	}

	// Save to export directory
	exportDir := "/var/exports"
	outputPath := filepath.Join(exportDir, filename)
	outFile, err := os.Create(outputPath)
	if err != nil {
		http.Error(w, "failed to create output file", http.StatusInternalServerError)
		return
	}
	defer outFile.Close()

	// Stream content to file
	_, err = io.Copy(outFile, resp.Body)
	if err != nil {
		http.Error(w, "failed to write report", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
	w.Write([]byte("report exported successfully"))
}


