package config

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
)

// RemoteConfigLoader 从远程URL加载配置文件
type RemoteConfigLoader struct {
	BaseURL    string
	HTTPClient *http.Client
}

// LoadConfig 根据用户提供的路径加载远程配置
func (l *RemoteConfigLoader) LoadConfig(userPath string) (map[string]interface{}, error) {
	// 构建完整的配置URL
	configURL := l.BaseURL + "/configs/" + userPath

	// 发起HTTP请求获取配置
	resp, err := l.HTTPClient.Get(configURL)
	if err != nil {
		return nil, fmt.Errorf("failed to fetch config: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("config server returned status: %d", resp.StatusCode)
	}

	// 读取响应体
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("failed to read response body: %w", err)
	}

	// 解析JSON配置
	var config map[string]interface{}
	if err := json.Unmarshal(body, &config); err != nil {
		return nil, fmt.Errorf("failed to parse config JSON: %w", err)
	}

	return config, nil
}

// LoadFromFile 从本地文件加载配置（辅助方法）
func LoadFromFile(path string) (map[string]interface{}, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}

	var config map[string]interface{}
	if err := json.Unmarshal(data, &config); err != nil {
		return nil, err
	}
	return config, nil
}


