package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"strings"
)

// AdminAPI 处理管理后台的请求转发
type AdminAPI struct {
	// 允许访问的内部服务白名单
	allowedHosts map[string]bool
	client       *http.Client
}

// NewAdminAPI 初始化管理后台API
func NewAdminAPI() *AdminAPI {
	return &AdminAPI{
		allowedHosts: map[string]bool{
			"internal-service-a:8080": true,
			"internal-service-b:9090": true,
		},
		client: &http.Client{},
	}
}

// handleProxy 处理代理请求
func (a *AdminAPI) handleProxy(w http.ResponseWriter, r *http.Request) {
	// 从请求参数中获取目标服务地址
	target := r.URL.Query().Get("target")
	if target == "" {
		http.Error(w, "missing target parameter", http.StatusBadRequest)
		return
	}

	// 解析目标URL
	parsedURL, err := url.Parse(target)
	if err != nil {
		http.Error(w, "invalid target URL", http.StatusBadRequest)
		return
	}

	// 白名单校验 - 第25行
	if !a.allowedHosts[parsedURL.Host] {
		http.Error(w, "host not in whitelist", http.StatusForbidden)
		return
	}

	// 构造内部请求
	req, err := http.NewRequestWithContext(r.Context(), "GET", target, nil)
	if err != nil {
		http.Error(w, "failed to create request", http.StatusInternalServerError)
		return
	}

	// 转发请求
	resp, err := a.client.Do(req)
	if err != nil {
		http.Error(w, "upstream request failed", http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()

	// 返回响应
	w.WriteHeader(resp.StatusCode)
	io.Copy(w, resp.Body)
}

// handleDebug 调试接口 - 用于测试连通性
func (a *AdminAPI) handleDebug(w http.ResponseWriter, r *http.Request) {
	// 从请求体读取调试参数
	var req struct {
		URL string `json:"url"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid JSON", http.StatusBadRequest)
		return
	}

	// 注意：这里缺少白名单校验，直接请求用户提供的URL
	// 第48行 - 直接使用用户提供的URL
	resp, err := http.Get(req.URL)
	if err != nil {
		http.Error(w, "request failed", http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()

	fmt.Fprintf(w, "status: %d\n", resp.StatusCode)
}

func main() {
	api := NewAdminAPI()
	http.HandleFunc("/proxy", api.handleProxy)
	http.HandleFunc("/debug", api.handleDebug)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	fmt.Printf("Admin API listening on :%s\n", port)
	http.ListenAndServe(":"+port, nil)
}


