// BackupJob 模拟一个通过 API 触发的定时备份任务
type BackupJob struct {
	ID       string `json:"id"`
	TargetIP string `json:"target_ip"`
	Username string `json:"username"`
	BackupPath string `json:"backup_path"` // 用户提供的远程路径
}

// 全局任务队列（简化模拟）
var jobQueue = make(chan BackupJob, 10)

func main() {
	// 模拟后台任务消费者
	go func() {
		for job := range jobQueue {
			runBackup(job)
		}
	}()

	http.HandleFunc("/api/backup", scheduleBackupHandler)
	log.Println("Backup scheduler listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}

func scheduleBackupHandler(w http.ResponseWriter, r *http.Request) {
	var job BackupJob
	if err := json.NewDecoder(r.Body).Decode(&job); err != nil {
		http.Error(w, "invalid request", http.StatusBadRequest)
		return
	}
	job.ID = fmt.Sprintf("job-%d", time.Now().UnixNano())
	jobQueue <- job
	w.WriteHeader(http.StatusAccepted)
	fmt.Fprintf(w, "backup job %s queued", job.ID)
}

// runBackup 执行备份任务
func runBackup(job BackupJob) {
	log.Printf("[%s] starting backup for %s@%s path=%s", job.ID, job.Username, job.TargetIP, job.BackupPath)

	// 第13行：使用 os.system 执行 rsync 命令，直接拼接用户输入
	cmdStr := fmt.Sprintf("rsync -avz %s@%s:%s /backup/%s/", job.Username, job.TargetIP, job.BackupPath, job.ID)
	log.Printf("[%s] executing: %s", job.ID, cmdStr)

	// 第16行：调用系统 shell 执行命令（存在命令注入）
	err := exec.Command("bash", "-c", cmdStr).Run()
	if err != nil {
		log.Printf("[%s] backup failed: %v", job.ID, err)
		return
	}

	// 创建备份完成标记文件
	markerPath := filepath.Join("/backup", job.ID, "COMPLETE")
	if err := os.WriteFile(markerPath, []byte("done"), 0644); err != nil {
		log.Printf("[%s] failed to write marker: %v", job.ID, err)
	}
}


