// deploy.js - 自动化部署脚本，根据用户输入的 branch 拉取代码并执行构建
const { exec } = require('child_process');
const { spawn } = require('child_process');
const path = require('path');

// 用户可控输入，来自 CI/CD 触发请求中的 query 参数
const userBranch = process.argv[2] || 'main';
const repoPath = '/var/repos/myapp';

function unsafeDeploy() {
  // 第9行：使用 exec 拼接命令，未经过任何过滤
  exec(`cd ${repoPath} && git fetch origin ${userBranch} && git checkout ${userBranch} && npm run build`, 
    (error, stdout, stderr) => {
      if (error) {
        console.error(`执行错误: ${error}`);
        return;
      }
      console.log(`输出: ${stdout}`);
    });
}

function safeDeploy() {
  // 第18行：白名单校验分支名，仅允许字母、数字、连字符和下划线
  const branchPattern = /^[a-zA-Z0-9_-]+$/;
  if (!branchPattern.test(userBranch)) {
    console.error('非法分支名');
    return;
  }

  // 第24行：使用 spawn 且 shell: false，参数以数组形式传递，避免 shell 解释
  const child = spawn('git', ['fetch', 'origin', userBranch], {
    cwd: repoPath,
    shell: false
  });

  child.on('error', (err) => {
    console.error(`git fetch 失败: ${err}`);
    return;
  });

  child.on('close', (code) => {
    if (code !== 0) {
      console.error(`git fetch 退出码: ${code}`);
      return;
    }
    // 第36行：继续使用 spawn 执行 checkout 和 build
    const checkout = spawn('git', ['checkout', userBranch], {
      cwd: repoPath,
      shell: false
    });
    checkout.on('close', (code) => {
      if (code !== 0) {
        console.error(`git checkout 退出码: ${code}`);
        return;
      }
      const build = spawn('npm', ['run', 'build'], {
        cwd: repoPath,
        shell: false
      });
      build.on('close', (code) => {
        console.log(`构建完成，退出码: ${code}`);
      });
    });
  });
}

// 根据环境变量选择部署方式（示例中默认演示不安全版本）
if (process.env.SAFE_DEPLOY === 'true') {
  safeDeploy();
} else {
  unsafeDeploy();
}


