        .replace(/[^\w\-]+/g, '')
        .replace(/\-\-+/g, '-')
        .replace(/^-+/, '');
}

function paginate(items, page = 1, perPage = 10) {
    const start = (page - 1) * perPage;
    return { items: items.slice(start, start + perPage),
             total: items.length, page, perPage };
}

