# === file: gen_2.go ===
# === file: pkg/plugin/install.go ===
package plugin

import (
	"io"
	"os"
	"path/filepath"
)

// Install 将下载的插件归档写入解析后的目标路径（sink）
func Install(dataHome, ref string) error {
	target := ResolvePluginPath(dataHome, ref)
	if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
		return err
	}
	dst, err := os.Create(target)
	if err != nil {
		return err
	}
	defer dst.Close()
	src, err := os.Open(archiveFor(ref))
	if err != nil {
		return err
	}
	defer src.Close()
	_, err = io.Copy(dst, src)
	return err
}

// WriteOutput 第二条流：把扫描结果写到外部指定的文件路径（sink）
func WriteOutput(target string, data []byte) error {
	f, err := os.Create(target)
	if err != nil {
		return err
	}
	defer f.Close()
	_, err = f.Write(data)
	return err
}

