<?php
// framework/core/TemplateEngine.php
class TemplateEngine {
    private $templateDir;
    private $cache = [];

    public function __construct($dir) {
        $this->templateDir = rtrim($dir, '/');
    }

    public function render($templateName, $context) {
        $file = $this->templateDir . '/' . $templateName . '.php';
        if (!file_exists($file)) {
            throw new Exception("Template not found: $templateName");
        }

        // 提取模板中的 {{ variable }} 占位符
        $content = file_get_contents($file);
        preg_match_all('/\{\{\s*(\w+)\s*\}\}/', $content, $matches);

        // 将上下文中的值替换到模板
        foreach ($matches[1] as $var) {
            if (isset($context[$var])) {
                $value = $context[$var];
                // 防御：尝试转义 HTML 特殊字符（但仅对字符串类型有效）
                if (is_string($value)) {
                    $value = htmlspecialchars($value, ENT_QUOTES, 'UTF-8');
                }
                // 替换占位符
                $content = str_replace("{{ $var }}", $value, $content);
            }
        }

        // 将处理后的模板内容作为 PHP 代码执行（模拟模板渲染）
        ob_start();
        eval('?>' . $content);
        $output = ob_get_clean();
        return $output;
    }
}

