    private $routes = [];

    public function addRoute($path, $handler) {
        $this->routes[$path] = $handler;
    }

    public function dispatch($uri) {
        if (isset($this->routes[$uri])) {
            return call_user_func($this->routes[$uri]);
        }
        return "404 Not Found";
    }
}

