class FileBackup {
public:
    FileBackup(const char* path) : m_path(path), m_data(nullptr), m_size(0) {
        load_file();
    }

    ~FileBackup() {
        if (m_data) {
            free(m_data);
            m_data = nullptr;
        }
    }

    // 重建备份：重新读取文件内容
    bool reload() {
        if (m_data) {
            free(m_data);  // line 21: 释放旧数据
            m_data = nullptr;
        }
        load_file();
        return m_data != nullptr;
    }

    const char* data() const { return m_data; }
    size_t size() const { return m_size; }

private:
    void load_file() {
        int fd = open(m_path.c_str(), O_RDONLY);
        if (fd < 0) return;

        struct stat st;
        if (fstat(fd, &st) != 0 || st.st_size <= 0) {
            close(fd);
            return;
        }

        m_size = static_cast<size_t>(st.st_size);
        m_data = static_cast<char*>(malloc(m_size + 1));
        if (!m_data) {
            close(fd);
            return;
        }

        ssize_t bytes = read(fd, m_data, m_size);
        close(fd);
        if (bytes != static_cast<ssize_t>(m_size)) {
            free(m_data);  // line 45: 读取失败，释放已分配内存
            m_data = nullptr;
            m_size = 0;
            return;
        }
        m_data[m_size] = '\0';
    }

    std::string m_path;
    char* m_data;
    size_t m_size;
};

int main() {
    const char* cfg = "/tmp/backup.dat";
    FileBackup backup(cfg);
    if (!backup.data()) {
        printf("初始加载失败\n");
        return 1;
    }

    // 模拟文件更新后重新加载
    backup.reload();  // line 63: 第一次 reload，正常释放并重新加载
    backup.reload();  // line 64: 第二次 reload，触发 double free

    printf("数据大小: %zu\n", backup.size());
    return 0;
}


