class ConfigLoader:
    def __init__(self):
        self._config = {}
        self._watcher = None

    def load(self):
        """加载配置文件，并启动文件监控"""
        try:
            with open(CONFIG_PATH, 'r') as f:
                self._config = json.load(f)
        except FileNotFoundError:
            self._config = {}

        # 启动文件监控线程
        self._watcher = self._start_watcher()
        print("配置加载完成，监控已启动")

    def _start_watcher(self):
        """模拟启动一个监控线程（实际会返回线程对象）"""
        import threading
        t = threading.Thread(target=self._watch_loop)
        t.daemon = True
        t.start()
        return t

    def _watch_loop(self):
        """监控文件变化（简化实现）"""
        import time
        last_mtime = 0
        while True:
            try:
                mtime = os.path.getmtime(CONFIG_PATH)
                if mtime != last_mtime:
                    last_mtime = mtime
                    # 重新加载配置
                    self.reload()
            except FileNotFoundError:
                pass
            time.sleep(2)

    def reload(self):
        """重新加载配置（供监控线程调用）"""
        with open(CONFIG_PATH, 'r') as f:
            self._config = json.load(f)

    def get(self, key, default=None):
        return self._config.get(key, default)

    def close(self):
        """关闭资源，停止监控"""
        if self._watcher:
            # 尝试停止线程（此处仅为演示）
