package main

import (
	"context"
	"fmt"
	"log"
	"os/exec"
	"strings"
	"time"
)

// WhitelistedCommands defines the only commands that can be scheduled
var WhitelistedCommands = map[string]bool{
	"backup":     true,
	"cleanup":    true,
	"healthcheck": true,
}

// scheduledTask represents a cron-like job definition
type scheduledTask struct {
	Name        string
	Command     string
	Args        []string
	Schedule    string
}

// runTask executes a scheduled task safely
func runTask(ctx context.Context, task scheduledTask) error {
	// Validate task name against whitelist
	if !WhitelistedCommands[task.Name] {
		return fmt.Errorf("task %q is not whitelisted", task.Name)
	}

	// Build command with explicit list arguments, never a shell string
	cmd := exec.CommandContext(ctx, task.Command, task.Args...)

	// Explicitly disable shell invocation
	cmd.Shell = false

	log.Printf("Executing task %s with args: %v", task.Name, task.Args)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("task %s failed: %v, output: %s", task.Name, err, string(output))
	}

	log.Printf("Task %s completed successfully", task.Name)
	return nil
}

// scheduleTasks simulates a scheduler that parses user-provided task definitions
func scheduleTasks(tasks []scheduledTask) {
	ctx := context.Background()
	for _, task := range tasks {
		// Simulate cron-like scheduling
		go func(t scheduledTask) {
			ticker := time.NewTicker(1 * time.Minute)
			defer ticker.Stop()
			for {
				select {
				case <-ctx.Done():
					return
				case <-ticker.C:
					if err := runTask(ctx, t); err != nil {
						log.Printf("Scheduled task error: %v", err)
					}
				}
			}
		}(task)
	}
}

