#include <cstdio>
#include <cstdlib>
#include <pthread.h>

class Buffer {
public:
    int* data;
    int size;
    Buffer(int sz) : size(sz) {
        data = (int*)malloc(sizeof(int) * size);
        if (!data) {
            size = 0;
        }
    }
    ~Buffer() {
        if (data) {
            free(data);
            data = nullptr;
        }
    }
};

pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;
int* g_shared = nullptr;
int g_len = 0;

void release_shared() {
    pthread_mutex_lock(&g_mutex);
    if (g_shared) {
        free(g_shared);
        g_shared = nullptr;  // 防御：置NULL
    }
    pthread_mutex_unlock(&g_mutex);
}

void* worker(void* arg) {
    int id = *(int*)arg;
    for (int i = 0; i < 3; ++i) {
        pthread_mutex_lock(&g_mutex);
        if (g_shared) {
            // 模拟使用共享缓冲区
            printf("Thread %d reading g_shared[0]=%d\n", id, g_shared[0]);
        }
        pthread_mutex_unlock(&g_mutex);
        usleep(1000);
    }
    // 每个线程都尝试释放
    release_shared();
    return nullptr;
}

int main() {
    g_len = 4;
    g_shared = (int*)malloc(sizeof(int) * g_len);
    if (!g_shared) return 1;
    for (int i = 0; i < g_len; ++i) g_shared[i] = i;

    pthread_t t1, t2;
    int id1 = 1, id2 = 2;
    pthread_create(&t1, nullptr, worker, &id1);
    pthread_create(&t2, nullptr, worker, &id2);

    pthread_join(t1, nullptr);
    pthread_join(t2, nullptr);

    // 主线程再次释放（第三次释放）
    release_shared();

    pthread_mutex_destroy(&g_mutex);
    return 0;
}


